INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Jugendliche immer bis 22 Uhr arbeiten dürfen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Standard ist bis 20 Uhr, mit Ausnahmen"}, {"text": "Ja", "correct": false, "because": "Zu pauschal"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich einen Jugendlichen für IT-Support einplane?', 3, '[{"text": "Arbeitszeitregelung", "correct": true, "because": "Schützt vor Überlastung"}, {"text": "Schnelle Hardware", "correct": false, "because": "Nicht primär relevant"}, {"text": "Projektfristen", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Regeln gelten für Jugendliche in der IT-Ausbildung?', 5, '[{"text": "Max. 8 Stunden täglich", "correct": true, "because": "Schützt Gesundheit"}, {"text": "Mind. 30 Minuten Pause", "correct": true, "because": "Bei über 4,5 Stunden Pflicht"}, {"text": "Nachtarbeit erlaubt", "correct": false, "because": "Nur in Ausnahmen"}, {"text": "40-Stunden-Woche immer", "correct": false, "because": "Maximalgrenze"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Jugendliche dürfen nicht am Sonntag arbeiten. b) Pausen sind optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Pausen sind Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich einen Jugendlichen für Serverwartung einsetze?', 4, '[{"text": "Arbeitszeitgrenzen", "correct": false, "because": "Müssen eingehalten werden"}, {"text": "Pausenregelung", "correct": false, "because": "Pflicht für Gesundheit"}, {"text": "Büroausstattung", "correct": true, "because": "Kein direkter Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 16-Jährige in der IT Überstunden machen dürfen?', 2, '[{"text": "Nein", "correct": true, "because": "Überstunden sind verboten"}, {"text": "Ja", "correct": false, "because": "Schutz vor Überlastung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Regel wähle ich für einen Jugendlichen im IT-Praktikum?', 3, '[{"text": "5-Tage-Woche", "correct": true, "because": "Maximal erlaubt"}, {"text": "10-Stunden-Schicht", "correct": false, "because": "Zu lang"}, {"text": "Nachtschicht", "correct": false, "because": "Nur in Ausnahmen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren schützen Jugendliche bei IT-Arbeit?', 5, '[{"text": "Arbeitszeitbegrenzung", "correct": true, "because": "Verhindert Überlastung"}, {"text": "Pausenregelung", "correct": true, "because": "Fördert Erholung"}, {"text": "Höhere Gehälter", "correct": false, "because": "Kein Schutzfaktor"}, {"text": "Schnelle PCs", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Jugendliche haben mehr Urlaub. b) Sie dürfen nachts arbeiten. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nachtarbeit stark eingeschränkt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um einen Jugendlichen für Netzwerkaufgaben einzusetzen?', 4, '[{"text": "Pausenplan", "correct": false, "because": "Pflicht für Erholung"}, {"text": "Zeiterfassung", "correct": false, "because": "Notwendig für Kontrolle"}, {"text": "Firmenlogo", "correct": true, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Dürfen 15-Jährige in der IT vollzeit arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Nur leichte Tätigkeiten erlaubt"}, {"text": "Ja", "correct": false, "because": "Schulpflicht hat Vorrang"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt die Regelung für Jugendliche in der IT?', 4, '[{"text": "Gesundheitsschutz", "correct": true, "because": "Verhindert Überlastung"}, {"text": "Mehr Freizeit", "correct": true, "because": "Fördert Entwicklung"}, {"text": "Schnellere Beförderung", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Jugendliche an Feiertagen immer frei haben. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Ausnahmen in bestimmten Branchen"}, {"text": "Ja", "correct": false, "because": "Zu pauschal"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist entscheidend, wenn ich einen Jugendlichen für Softwaretests einsetze?', 3, '[{"text": "Arbeitszeitkontrolle", "correct": true, "because": "Sichert Einhaltung"}, {"text": "Neue Software", "correct": false, "because": "Nicht primär"}, {"text": "Bunte Monitore", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Jugendliche brauchen 12 Stunden Freizeit täglich. b) Samstagsarbeit ist immer verboten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Samstagsarbeit in Ausnahmen erlaubt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich für Jugendliche bei Hardwareaufgaben?', 5, '[{"text": "Keine gefährlichen Arbeiten", "correct": true, "because": "Schützt Gesundheit"}, {"text": "Arbeitszeitbegrenzung", "correct": true, "because": "Fördert Erholung"}, {"text": "Hohe Gehälter", "correct": false, "because": "Kein Schutzfaktor"}, {"text": "Schnelle Ergebnisse", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich einen Jugendlichen für IT-Support einplane?', 3, '[{"text": "Pausenregelung", "correct": false, "because": "Pflicht für Erholung"}, {"text": "Arbeitszeitgrenze", "correct": false, "because": "Muss eingehalten werden"}, {"text": "Firmenfarben", "correct": true, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Dürfen Jugendliche in der IT Akkordarbeit machen?', 3, '[{"text": "Nein", "correct": true, "because": "Verboten wegen Stress"}, {"text": "Ja", "correct": false, "because": "Nicht erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Jugendliche in der IT an Brückentagen arbeiten dürfen?', 2, '[{"text": "Ja", "correct": true, "because": "Mit Ausgleich erlaubt"}, {"text": "Nein", "correct": false, "because": "Nicht grundsätzlich verboten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend, wenn ich einen Jugendlichen für Datenbankaufgaben einsetze?', 4, '[{"text": "Zeitplanung", "correct": true, "because": "Sichert Einhaltung von Regeln"}, {"text": "Neue Software", "correct": false, "because": "Nicht primär"}, {"text": "Bunter Bildschirm", "correct": false, "because": "Irrelevant"}]');
